mapper.select:
select 
from seckill_sku
where activity_id = #{activityId}
  and sku_id = #{skuId}
  and is_deleted = 0

mapper.delete:
delete from seckill_sku
where activity_id = #{activityId}
  and status = 0

mapper.update:
update seckill_sku
set status = #{targetStatus}, update_time = now()
where activity_id = #{activityId}
  and status = #{expectedStatus}
  and is_deleted = 0
